/**
 * Extract Gemini NL Query Response
 */
const items = $input.all();
const results = [];
const prepData = $('Prepare NL Query Context').first()?.json || {};
const chatId = prepData.chat_id;

for (const item of items) {
  const json = item.json;
  const rawAnswer = json.candidates?.[0]?.content?.parts?.[0]?.text || "I could not find that in the records.";

  results.push({
    json: {
      chat_id: chatId,
      answer: rawAnswer.trim()
    }
  });
}

return results;
